#!/usr/bin/env python3
"""Summarize the small P5 geometry/field falsifier without hiding unsupported plans."""
import argparse,collections,hashlib,json,os,tempfile
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--probe',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output;out.mkdir(exist_ok=False);path=a.probe/'probe.stdout';rows=[json.loads(line) for line in path.read_text().splitlines()];plans=[r for r in rows if r['phase']=='plan'];samples=[r for r in rows if r['phase']=='scalar'];summary=next(r for r in rows if r['phase']=='summary');targets=sorted(set(r['point'] for r in plans));assert len(targets)==48 and len(plans)==144
for r in plans:
 if r['status']=='ready':assert r['rank']==56 and r['condition']<=1e8 and r['reproduction']<=1e-10 and r['value_l1']<=16 and r['gradient_l1']<=32 and r['hessian_l1']<=64
rejected=collections.Counter((r['donors'],r['status']) for r in plans if r['status']!='ready');first={point:next((r['donors'] for r in plans if r['point']==point and r['status']=='ready'),None) for point in targets};coverage=collections.Counter(first.values());analysis={'scope':'48-target geometry-only Cartesian P5 probe; full56columns retained; no production/evolution/all-domain acceptance','summary':summary,'guards':{'rank':56,'maximum_condition':1e8,'maximum_reproduction':1e-10,'value_l1':16,'scaled_gradient_l1':32,'scaled_hessian_l1':64},'rejections':[{'donors':k[0],'status':k[1],'count':v} for k,v in rejected.items()],'first_guard_accepted_support_counts':{str(k):v for k,v in coverage.items()},'target126':[r for r in rows if r.get('point')==126],'matched_first_guard_accepted_errors':{},'scientific_acceptance':False,'conclusion':'Exact Cartesian polynomial moments and bounded weights do not ensure good approximation of actual positive fields on a broad donor footprint. At point126 both log and direct-physical P5 are worse than original FD4; P5 is not adopted.'}
for storage in ['positive_log','direct_physical']:
 for field in ['chi','alpha']:
  for angular in [0,1]:
   selected=[r for r in samples if r['field']==field and r.get('storage','positive_log')==storage and r['angular']==angular and r['donors']==first[r['point']]]
   analysis['matched_first_guard_accepted_errors'][str((storage,field,angular))]={'queries':len(selected),'maximum_gradient_error':max(r['gradient_error'] for r in selected),'maximum_hessian_error':max(r['hessian_error'] for r in selected),'maximum_H_error':max(abs(r['H_error']) for r in selected),'maximum_scaled_noise':max(r['scaled_noise'] for r in selected)}
with tempfile.TemporaryDirectory(prefix='p5-plot-',dir=out) as cache:
 os.environ['MPLCONFIGDIR']=cache;os.environ['XDG_CACHE_HOME']=cache
 import matplotlib;matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 fig,axes=plt.subplots(1,2,figsize=(11,5),layout='constrained');initial=Path('docs/elliptic-shift-3d/evidence/transition-jet-localization-20261027/diagnose.stdout');sixth=Path('docs/elliptic-shift-3d/evidence/transition-order-study-r3-20261027/n6_amr3-diagnose.stdout');initial_rows=[json.loads(line) for line in initial.read_text().splitlines()];sixth_rows=[json.loads(line) for line in sixth.read_text().splitlines()];original_H=next(r['H'] for r in initial_rows if r.get('phase')=='target' and r['method']=='default_supported');sixth_H=next(r['H'] for r in sixth_rows if r.get('phase')=='target' and r['method']=='sixth_transition');p5_values={r.get('storage','positive_log'):r['H'] for r in samples if r['point']==126 and r['donors']==256 and r['field']=='chi' and r['angular']==0};analysis['baseline_plot_source_hashes']={str(f):hashlib.sha256(f.read_bytes()).hexdigest() for f in [initial,sixth]};values=[abs(original_H),abs(sixth_H),abs(p5_values['positive_log']),abs(p5_values['direct_physical'])];labels=['Original FD4','Transition FD6','P5 log,256','P5 physical,256'];axes[0].bar(range(4),values);axes[0].set_xticks(range(4),labels,rotation=30,ha='right');axes[0].set_ylabel('|H|');axes[0].set_title('Point126: guarded P5 still worsens actual profile')
 ready=collections.Counter(r['donors'] for r in plans if r['status']=='ready');notready=collections.Counter(r['donors'] for r in plans if r['status']!='ready');supports=[125,175,256];axes[1].bar(range(3),[ready[n] for n in supports],label='ready');axes[1].bar(range(3),[notready[n] for n in supports],bottom=[ready[n] for n in supports],label='explicitly rejected');axes[1].set_xticks(range(3),supports);axes[1].set_xlabel('nearest actual active donors');axes[1].set_ylabel('queries');axes[1].legend();fig.suptitle('Physical P5 falsifier: exact moments are necessary, not sufficient\nNo guard relaxation, field projection or production adoption');fig.savefig(out/'p5-falsifier.png',dpi=150);plt.close(fig)
analysis['source_sha256']=hashlib.sha256(path.read_bytes()).hexdigest();analysis['script_sha256']=hashlib.sha256(Path(__file__).read_bytes()).hexdigest();(out/'analysis.json').write_text(json.dumps(analysis,indent=2,allow_nan=False)+'\n');print(json.dumps({'ready':summary['plans_ready'],'rejected':summary['plans_rejected'],'coverage':dict(coverage),'target126_P5_failed':True}))
